/* Connected product improvements. Existing API, storage and save contracts remain. */
ICONS.share='<path d="M12 16V3m-5 5 5-5 5 5M5 13v7h14v-7"/>';
ICONS.grid='<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>';
ICONS.list='<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>';
let agentRequests=[],officeContacts=[],discoveryLayout='grid',publicCalendarEvents=new Map(),contributionPresentation={};
const experienceApiBase=api;
api=async function(path,method='GET',data){if(path==='/api/v3/contributions'&&method==='POST')data={...data,...contributionPresentation};const r=await experienceApiBase(path,method,data);if(path==='/api/bootstrap'&&r.profile&&!demoMode){agentRequests=(await liveApi('/api/v3/agent-requests')).requests;officeContacts=(await liveApi('/api/v3/contacts')).contacts;}return r};
const localDate=()=>new Date(Date.now()+7200000).toISOString().slice(0,10);
const realMember=id=>toServer({id}).id;
function officeHasUpdates(){return platformActivity.length>0||threads.some(t=>t.unread)||agentRequests.some(r=>r.to===account.profile?.id&&r.status==='Pending')||state.invitations.some(i=>i.to==='me'&&i.status==='Pending')||officeProjects.some(p=>p.status==='Invitation')}
function updateOfficeBadges(){const active=officeHasUpdates();document.querySelectorAll('[data-office-nav]').forEach(el=>{el.classList.toggle('has-updates',active);el.setAttribute('aria-label',active?'Office, new notifications':'Office');const old=el.querySelector('.nav-notification');if(active&&!old)el.insertAdjacentHTML('beforeend','<span class="nav-notification" aria-hidden="true"></span>');if(!active)old?.remove()})}
renderApp=function(){const navs=[['feed','feed','Feed'],['discover','search','Discover'],...(account.profile?[['office','brief','Office']]:[]),['profile','user',account.profile?'My profile':'Join TAPPED IN']];const navButton=([v,i,l],mobile=false)=>`<button ${v==='office'?'data-office-nav':''} class="${mobile?'mobile-item':'nav'} ${view===v?'active':''}" aria-label="${l}" ${view===v?'aria-current="page"':''} onclick="${v==='profile'?"openProfile('me')":`nav('${v}')`}">${icon(i)}${mobile?'':`<span>${l}</span>`}</button>`;const mobile=[navs[0],navs[1],null,...navs.slice(2)];document.getElementById('app').innerHTML=`<header class="top"><button class="brand" aria-label="TAPPED IN feed" onclick="nav('feed')">TAPPED<span>IN</span></button><div class="topright"><button class="icon-btn" aria-label="Change theme" onclick="toggleTheme()">${icon(state.theme==='dark'?'sun':'moon')}</button><button class="icon-btn" aria-label="Account settings" onclick="account.profile?nav('settings'):location.assign('/login')">${icon('user')}</button></div></header><div class="shell"><aside class="side">${navs.map(n=>navButton(n)).join('')}<button class="btn primary" onclick="tapMenu()">${icon('plus')}Tap In</button><div class="sidefoot">${account.profile?`<button class="side-profile" onclick="openProfile('me')"><b>${esc(me().name)}</b><span>${esc(identityCategory(me()))}</span><span>${esc(me().city)}${me().country?', '+esc(me().country):''}</span></button>`:''}</div></aside><main class="main" id="main">${renderView()}</main><aside class="rail">${renderRail()}</aside></div><nav class="mobile-nav" aria-label="Main navigation">${mobile.map(n=>n?navButton(n,true):`<button class="mobile-tap" aria-label="Tap In, create a post" onclick="tapMenu()">${icon('plus')}</button>`).join('')}</nav>`;updateOfficeBadges()};
const renderExperienceBase=render;
render=function(){renderExperienceBase();updateOfficeBadges();enhanceSearches();if(route==='app'&&view==='profile')loadCalendarProjects(activeProfile)};
setInterval(async()=>{if(!account.profile||document.hidden)return;try{platformActivity=(await liveApi('/api/v3/platform-state')).activity;agentRequests=(await liveApi('/api/v3/agent-requests')).requests;updateOfficeBadges()}catch{}},20000);
const feedExperienceBase=renderFeed;
renderFeed=function(){return feedExperienceBase().replace(/<div class="community-actions">[\s\S]*?<\/div>/,'')};
function cardOpen(event,id,contribution=false){if(event.target.closest('button,a,input,select,textarea'))return;contribution?openProfileContribution(id):state.posts.find(p=>p.id===id)?.opp?openOpportunity(state.posts.find(p=>p.id===id).opp):openWork(id)}
function cardActions(p,contribution=false){const starred=state.likes.includes(p.id),saved=state.saved.includes(p.id),own=contribution?p.by===account.profile?.id:p.by==='me';return `<div class="post-actions"><button aria-label="Star ${esc(p.title)}" aria-pressed="${starred}" class="${starred?'selected':''}" onclick="react('likes','${p.id}')">${icon('star')}${Number(p.likes||0)+(starred?1:0)}</button><button aria-label="Save ${esc(p.title)}" aria-pressed="${saved}" class="${saved?'selected':''}" onclick="react('saved','${p.id}')">${icon('save')}</button><button aria-label="Share ${esc(p.title)}" onclick="sharePost('${p.id}')">${icon('share')}</button><button aria-label="Repost ${esc(p.title)}" aria-pressed="${state.reposts.includes(p.id)}" onclick="react('reposts','${p.id}')">${icon('repost')}</button>${own?`<button class="text-btn highlight-action" aria-pressed="${(me().highlights||[]).includes(p.id)}" onclick="toggleHighlight('${p.id}')">${(me().highlights||[]).includes(p.id)?'Highlighted':'Highlight'}</button>`:''}</div>`}
function postTags(p){return ['team','project'].filter(k=>p[k]).map(k=>{const item=officeProjects.find(x=>x.id===p[k]);return `<span class="tag">${k==='team'?'Team':'Project'}${p[k+'Name']||item?' · '+esc(p[k+'Name']||item.title):''}</span>`}).join('')}
artwork=function(p){const image=p.image||thumbnailCache.get(p.id)||youtubeThumbnail(p),orientation=p.imageOrientation||'landscape';return `<button class="media-cover ${orientation} ${image?'with-image':'no-image'}" ${p.image?'':`data-preview-post="${p.id}"`} onclick="${p.opp?`openOpportunity('${p.opp}')`:`openWork('${p.id}')`}" aria-label="Open ${esc(p.title)}">${image?`<img src="${esc(image)}" alt="" loading="lazy" width="1200" height="${orientation==='square'?1200:675}" onerror="this.remove()">`:''}<h3>${esc(p.title)}</h3></button>`};
function youtubeThumbnail(p){for(const l of p.links||[]){try{const u=new URL(l.url),id=u.hostname==='youtu.be'?u.pathname.slice(1):['youtube.com','www.youtube.com'].includes(u.hostname)?u.searchParams.get('v'):'';if(/^[a-zA-Z0-9_-]{11}$/.test(id))return 'https://i.ytimg.com/vi/'+id+'/hqdefault.jpg'}catch{}}return ''}
postCard=function(p){if(p.type!=='work'){const o=state.opps.find(x=>x.id===p.opp),by=person(p.by);if(!o)return '';const card={...o,...p,title:o.title};return `<article class="post" data-post-card="${p.id}" onclick="cardOpen(event,'${p.id}')"><div class="post-head row">${av(by)}<div>${profileButton(p.by)}<div class="meta">${esc(o.type==='brief'?'Brief / gig':'Collaboration')} · ${fmt(o.date)}</div></div></div>${artwork(card)}<div class="post-copy"><p>${esc(o.description)}</p><p class="meta">${esc(o.city)}${o.country?', '+esc(o.country):''} · ${money(o.budget)} · Apply by ${fmt(o.deadline)}</p><div class="row wrap gap8">${o.roles.map(r=>`<span class="tag">${esc(r)}</span>`).join('')}</div>${postTags(p)}</div>${cardActions(card)}</article>`}const by=person(p.by)||{name:'Member',roles:[]};return `<article class="post" data-post-card="${p.id}" onclick="cardOpen(event,'${p.id}')"><div class="post-head row">${av(by)}<div>${profileButton(p.by)}<div class="meta">${esc(identityCategory(by))} · ${fmt(p.date)}${p.date>localDate()?' · Upcoming work':''}</div></div><span class="post-type">${esc(p.workType)}</span></div>${artwork(p)}<div class="post-copy"><p>${esc(p.description)}</p>${postTags(p)}</div>${p.links?.length?`<div class="sources">${sourceLinks(p.links)}</div>`:''}<div class="credits"><div class="credit-list">${p.credits.map(creditChip).join('')}</div></div>${cardActions(p)}</article>`};
contributionCard=function(p){const by=contributionPerson(p.by)||{name:'Member'},image=p.image||thumbnailCache.get(p.id)||'';return `<article class="post community-post" data-post-card="${p.id}" onclick="cardOpen(event,'${p.id}',true)"><div class="post-head row">${av(by)}<div><button class="who" onclick="openProfile('${by.id||'me'}')">${esc(by.name)}</button><div class="meta">${esc(p.contribution)} · ${fmt(p.date)}${p.date>localDate()?' · Upcoming event':''}</div></div></div><button class="media-cover ${p.imageOrientation||'landscape'} ${image?'with-image':'no-image'}" ${p.image?'':`data-preview-post="${p.id}"`} aria-label="Open ${esc(p.title)}" onclick="openProfileContribution('${p.id}')">${image?`<img src="${esc(image)}" alt="" loading="lazy">`:''}<h3>${esc(p.title)}</h3></button><div class="post-copy"><p>${esc(p.description)}</p>${postTags(p)}${p.type==='checkin'?`<p>${esc(p.venueName||contributionPerson(p.venue)?.name||'Venue')} · ${esc(p.event)}</p>`:''}</div><div class="sources">${sourceLinks(p.links)}</div>${p.original?`<button class="text-btn original-link" onclick="openWork('${p.original}')">Original work</button>`:''}<div class="credits">${(p.tags||[]).map(t=>`<span class="tag">${esc(contributionPerson(t.person)?.name||'Member')} · ${esc(t.relation)}</span>`).join('')}</div>${cardActions(p,true)}</article>`};
async function toggleHighlight(id){const old=[...(me().highlights||[])],next=old.includes(id)?old.filter(x=>x!==id):[...old,id];if(next.length>10)return toast('You can keep up to 10 highlights. Remove one first.');me().highlights=next;try{await save();render();toast(next.includes(id)?'Added to highlights.':'Highlight removed.')}catch{me().highlights=old}}
function highlightSection(p){const ids=p.highlights||[];return `<section class="profile-highlights"><h3>Highlights <small>${ids.length} / 10</small></h3>${ids.length?`<div class="highlight-grid">${ids.map(id=>{const post=state.posts.find(x=>x.id===id)||contributions.find(x=>x.id===id);return post?`<button class="highlight-card" onclick="${post.type==='work'?`openWork('${id}')`:post.opp?`openOpportunity('${post.opp}')`:`openProfileContribution('${id}')`}">${post.image?`<img src="${esc(post.image)}" alt="" loading="lazy">`:icon('star')}<span>${esc(post.title||state.opps.find(o=>o.id===post.opp)?.title||'Post')}</span></button>`:''}).join('')}</div>`:p.id==='me'?'<p class="meta">Choose Highlight on any of your posts. Keep up to 10.</p>':'<p class="meta">No highlights selected yet.</p>'}</section>`}
const profileHeaderExperience=profileHeader;
profileHeader=function(p,own,work){const old=profileHeaderExperience(p,own,work).replace(renderProfileCalendar(p),'');const total=own?state.gigs.reduce((n,g)=>n+Number(g.amount||0),0):p.totalFees;return old.replace(`<b>${(own?state.socialLinks:p.links||[]).filter(l=>safeUrl(l.url)).length}</b><small>Social profiles</small>`,`<b>${total==null?icon('lock'):money(total)}</b><small>Total Fees recorded${total==null?' · Private':''}</small>`)+highlightSection(p)};
const profileExperienceBase=renderProfile;
renderProfile=function(){const p=person(activeProfile);if(!p)return profileExperienceBase();let html=profileExperienceBase();if(profileTab==='history')html+=renderProfileCalendar(p);return html};
const publicActivityExperience=publicProfileActivity;
publicProfileActivity=function(p){const a=publicActivityExperience(p);a.push(...(p.calendarStars||[]).map(s=>({...s,star:true})),...(p.id==='me'?[]:publicCalendarEvents.get(realMember(p.id))||[]));if(p.id==='me')for(const project of officeProjects.filter(x=>x.status!=='Invitation')){if(project.date)a.push({date:project.date,title:project.title,project:project.id,private:!project.publicCalendar});for(const t of project.tasks||[])if(t.due)a.push({date:t.due,title:t.title,project:project.id,private:true,task:t.id})}return a.filter(x=>/^\d{4}-\d{2}-\d{2}$/.test(x.date))};
async function loadCalendarProjects(id){const member=realMember(id);if(!member||publicCalendarEvents.has(member))return;publicCalendarEvents.set(member,[]);try{const {events}=await liveApi('/api/v3/calendar/'+member);publicCalendarEvents.set(member,events);if(view==='profile'&&activeProfile===id){const old=document.querySelector('.profile-calendar');if(old)old.outerHTML=renderProfileCalendar(person(id))}}catch{publicCalendarEvents.delete(member)}}
renderProfileCalendar=function(p){const current=localDate().slice(0,7);if(profileCalendarOwner!==p.id){profileCalendarOwner=p.id;profileCalendarMonth=current;profileCalendarDay=''}const [y,m]=profileCalendarMonth.split('-').map(Number),start=new Date(y,m-1,1),days=new Date(y,m,0).getDate(),activity=publicProfileActivity(p);return `<section class="profile-calendar"><div class="calendar-toolbar"><h3>Work calendar</h3><div class="row gap8"><button class="icon-btn" aria-label="Previous month" onclick="changeProfileMonth(-1)">‹</button><span aria-live="polite">${start.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</span><button class="icon-btn" aria-label="Next month" onclick="changeProfileMonth(1)">›</button></div><label class="calendar-jump">Go to date<input type="date" aria-label="Go to a custom date" value="${profileCalendarDay||localDate()}" onchange="jumpCalendarDate(this.value)"></label><button class="text-btn" onclick="resetProfileMonth()">Today</button></div><p class="meta">Tap any date to add work or an event. Stars mark moments.${p.id==='me'?' Private projects and tasks are visible only to you.':''}</p><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<span class="calendar-weekday">${d}</span>`).join('')}${'<span></span>'.repeat((start.getDay()+6)%7)}${Array.from({length:days},(_,i)=>{const date=profileCalendarMonth+'-'+String(i+1).padStart(2,'0'),events=activity.filter(a=>a.date===date);return `<button class="calendar-day ${events.length?'has-activity':''} ${date===profileCalendarDay?'selected':''} ${date===localDate()?'today':''}" aria-label="${date}, ${events.length} activities" aria-pressed="${date===profileCalendarDay}" onclick="openProfileDay('${date}')">${i+1}${events.some(a=>a.star)?`<span class="calendar-star">${icon('star')}</span>`:events.length?'<span class="calendar-dot"></span>':''}</button>`}).join('')}</div></section>`};
function jumpCalendarDate(date){if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return;profileCalendarMonth=date.slice(0,7);profileCalendarDay=date;render();openProfileDay(date)}
openProfileDay=function(date){const p=person(activeProfile);if(!p)return;profileCalendarDay=date;const activities=publicProfileActivity(p).filter(a=>a.date===date);modal(fmt(date),`<div class="stack">${activities.map(a=>`<article class="calendar-event"><h3>${a.star?icon('star'):''}${esc(a.title)}</h3>${a.description?`<p>${esc(a.description)}</p>`:''}${a.private?'<small>Private Office item</small>':''}<div class="row wrap gap8">${a.project?`<button class="btn" onclick="closeModal();openProject('${a.project}')">Open in Office</button>`:a.post?`<button class="btn" onclick="openWork('${a.post}')">Open work</button>`:a.contribution?`<button class="btn" onclick="openProfileContribution('${a.contribution}')">Open post</button>`:a.url?`<a class="btn" href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">View moment</a>`:''}${a.star&&p.id==='me'?`<button class="text-btn" onclick="editCalendarStar('${a.id}','${date}')">Edit star</button>`:''}</div></article>`).join('')||'<p>No work recorded on this date yet.</p>'}</div><p class="meta">${p.id==='me'?'Past and present dates record your work. Future dates show upcoming work and events.':'Add work with '+esc(p.name)+'. They confirm their own credit before it appears on their profile.'}</p>`,`<button class="btn" onclick="closeModal()">Done</button>${p.id==='me'?`<button class="btn" onclick="editCalendarStar('','${date}')">${icon('star')}Add moment</button>`:''}<button class="btn primary" onclick="calendarAddWork('${date}','${p.id}')">${p.id==='me'?'Add work / event':'Tap In'}</button>`)};
function calendarAddWork(date,id){if(!requireAccount(true))return;startComposer('work');composerData.date=date;composerData.title=id==='me'?'':'Work with '+person(id).name;composerData.credits=[{person:'me',role:me().primaryRole||me().roles[0],confirmed:true},...(id==='me'?[]:[{person:id,role:person(id).primaryRole||person(id).roles[0],confirmed:false}])];composerStep=1;drawComposer()}
renderMoments=function(p,own){return `<div class="row between"><h3>Stars on the calendar</h3>${own?'<button class="btn" onclick="editCalendarStar()">Add moment</button>':''}</div>${renderProfileCalendar(p)}${(own?state.moments:p.moments||[]).filter(m=>m.url).map(m=>`<article class="office-row"><div><h3>${esc(m.title)}</h3><p>${esc(m.text)}</p></div>${own?`<button class="btn" onclick="editCalendarStar('','',${JSON.stringify(m).replaceAll('"','&quot;')})">Place on calendar</button>`:`<a class="btn" href="${esc(m.url)}" target="_blank" rel="noopener noreferrer">View original</a>`}</article>`).join('')}`};
function editCalendarStar(id='',date=localDate(),legacy={}){const star=(me().calendarStars||[]).find(x=>x.id===id)||legacy;modal(id?'Edit calendar star':'Add calendar star',`<label>Moment title</label><input id="star-title" maxlength="120" value="${esc(star.title||'')}"><label>Date</label><input id="star-date" type="date" value="${star.date||date||localDate()}"><label>What happened?</label><textarea id="star-description" maxlength="500">${esc(star.description||star.text||'')}</textarea><label>Media link (optional)</label><input id="star-url" type="url" value="${esc(star.url||'')}"><div id="form-error" class="error"></div>`,`<button class="btn" onclick="closeModal()">Cancel</button>${id?`<button class="btn" onclick="removeCalendarStar('${id}')">Remove star</button>`:''}<button class="btn primary" onclick="saveCalendarStar('${id}')">Save star</button>`)}
async function saveCalendarStar(id){const star={id:id||uid(),title:document.getElementById('star-title').value.trim(),date:document.getElementById('star-date').value,description:document.getElementById('star-description').value,url:document.getElementById('star-url').value.trim()};if(!star.title||!star.date||star.url&&!safeUrl(star.url))return error('Add a title, date and a valid HTTPS link if used.');const old=me().calendarStars||[];if(!id&&old.length>=100)return error('You can keep up to 100 calendar stars.');me().calendarStars=[...old.filter(x=>x.id!==id),star];try{await save();closeModal();render()}catch{me().calendarStars=old}}
async function removeCalendarStar(id){if(!confirm('Remove this calendar star?'))return;const old=me().calendarStars;me().calendarStars=old.filter(x=>x.id!==id);try{await save();closeModal();render()}catch{me().calendarStars=old}}
// Composers retain one image and tags across every wizard step.
function projectTagFields(d={}){return `<div class="grid2"><div><label>Tag a project (optional)</label><select id="post-project"><option value="">No project</option>${officeProjects.filter(p=>p.type!=='team'&&p.status!=='Invitation').map(p=>`<option value="${p.id}" ${d.project===p.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select></div><div><label>Tag a team (optional)</label><select id="post-team"><option value="">No team</option>${officeProjects.filter(p=>p.type==='team'&&p.status!=='Invitation').map(p=>`<option value="${p.id}" ${d.team===p.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select></div></div><p class="meta">Tagged project and team names are public; workspace details stay private.</p><p class="meta">Post as ${esc(me().name)} · ${me().entityType==='business'?'Business / company':'Person'}. Credit people and businesses separately; each confirms their own role.</p>`}
function postImageFields(d={},target='work'){return `<section class="post-image-editor"><label for="post-image-file">One image (optional)</label><input id="post-image-file" type="file" accept="image/jpeg,image/png,image/webp" onchange="uploadPostImage(this,'${target}')"><label>Image orientation</label><select id="post-image-orientation" onchange="setPostOrientation(this.value,'${target}')">${options(['landscape','square'],d.imageOrientation||'landscape')}</select><div id="post-image-preview">${d.image?`<img src="${esc(d.image)}" alt="Selected post image"><button class="text-btn" onclick="removePostImage('${target}')">Remove image</button>`:''}</div><p id="post-image-status" class="meta" role="status">Landscape and square images only. Your title sits over a fading bottom edge.</p></section>`}
function setPostOrientation(value,target){(target==='work'?composerData:contributionPresentation).imageOrientation=value;const el=document.querySelector('#post-image-preview img');if(el)el.style.aspectRatio=value==='square'?'1':'16/9'}
function removePostImage(target){const d=target==='work'?composerData:contributionPresentation;d.image='';document.getElementById('post-image-preview').innerHTML=''}
let uploadingPostImage=false;
async function uploadPostImage(input,target){const file=input.files?.[0],note=document.getElementById('post-image-status');if(!file)return;if(file.size>5000000||!['image/jpeg','image/png','image/webp'].includes(file.type)){note.textContent='Choose one JPG, PNG or WebP image under 5 MB.';input.value='';return}uploadingPostImage=true;const buttons=[...document.querySelectorAll('#modal .dialog-foot .btn.primary')];buttons.forEach(b=>b.disabled=true);note.textContent='Uploading image…';try{const r=await fetch('/api/v3/post-image',{method:'POST',headers:{'content-type':file.type},body:file}),data=await r.json();if(!r.ok)throw new Error(data.error);const d=target==='work'?composerData:contributionPresentation;d.image=data.url;d.imageOrientation=document.getElementById('post-image-orientation')?.value||'landscape';if(input.isConnected){document.getElementById('post-image-preview').innerHTML=`<img src="${esc(data.url)}" alt="Selected post image" style="aspect-ratio:${d.imageOrientation==='square'?'1':'16/9'}"><button class="text-btn" onclick="removePostImage('${target}')">Remove image</button>`;note.textContent='Image ready.'}}catch(e){note.textContent=e.message}finally{uploadingPostImage=false;buttons.filter(b=>b.isConnected).forEach(b=>b.disabled=false)}}
const drawExperienceBase=drawComposer;
drawComposer=function(){drawExperienceBase();if(composerStep===1){document.getElementById('compose-date')?.removeAttribute('max');const description=document.getElementById('compose-description');if(description)description.insertAdjacentHTML('afterend',projectTagFields(composerData)+postImageFields(composerData));const paid=document.getElementById('compose-paid');if(paid)paid.insertAdjacentHTML('beforebegin','<p class="meta">Future dates represent upcoming work or events. Fees stay private.</p>')}enhanceSearches()};
const captureExperienceBase=captureComposer;
captureComposer=function(){captureExperienceBase();if(composerStep===1){composerData.project=document.getElementById('post-project')?.value||composerData.project||'';composerData.team=document.getElementById('post-team')?.value||composerData.team||'';if(composerData.city){const l=parseLocation(composerData.city,composerData.country);composerData.city=l.city;composerData.country=l.country}}};
const contributionComposerExperience=communityComposer;
communityComposer=function(type='tap',original=''){contributionPresentation={image:'',imageOrientation:'landscape',project:'',team:''};contributionComposerExperience(type,original);document.getElementById('tap-date')?.removeAttribute('max');document.getElementById('tap-description')?.insertAdjacentHTML('afterend',projectTagFields()+postImageFields({},'contribution'));enhanceSearches()};
const publishContributionExperience=publishContribution;
publishContribution=async function(type){if(uploadingPostImage)return error('Wait for the image upload.');contributionPresentation.project=document.getElementById('post-project')?.value||'';contributionPresentation.team=document.getElementById('post-team')?.value||'';return publishContributionExperience(type)};
// Discovery offers compact cards and a single-column list using the same result set.
personCard=function(p){return `<article class="person-card discovery-person"><button class="discovery-identity" onclick="openProfile('${p.id}')">${av(p)}<span><strong>${esc(p.name)}</strong><span class="meta">${esc(identityCategory(p))} · ${(p.roles||[]).map(esc).join(' / ')}</span><span class="meta">${esc(p.city)}${p.country?', '+esc(p.country):''}</span></span></button><button class="btn" onclick="toggleFollow('${p.id}')" aria-pressed="${state.follows.includes(p.id)}">${state.follows.includes(p.id)?'Following':'Follow'}</button></article>`};
const discoverExperienceBase=renderDiscover;
renderDiscover=function(){return discoverExperienceBase().replace('<div id="discover-results">',`<div class="discovery-layout row gap8"><span class="meta">View</span><button class="icon-btn" aria-label="Grid view" aria-pressed="${discoveryLayout==='grid'}" onclick="setDiscoveryLayout('grid')">${icon('grid')}</button><button class="icon-btn" aria-label="List view" aria-pressed="${discoveryLayout==='list'}" onclick="setDiscoveryLayout('list')">${icon('list')}</button></div><div id="discover-results" class="layout-${discoveryLayout}">`)};
function setDiscoveryLayout(layout){discoveryLayout=layout;const el=document.getElementById('discover-results');if(el)el.className='layout-'+layout;document.querySelectorAll('.discovery-layout button').forEach((b,i)=>b.setAttribute('aria-pressed',String(layout===(i===0?'grid':'list'))))}
// Searchable native selects keep the existing selected IDs and handlers.
function parseLocation(value,country=''){const parts=String(value||'').split(',').map(x=>x.trim());return {city:parts[0],country:parts.length>1?parts.slice(1).join(', '):country||locationDirectory.find(x=>x.city===parts[0])?.country||''}}
function enhanceSearches(){for(const select of document.querySelectorAll('select')){if(select.dataset.searchEnhanced)continue;const city=['join-city','edit-city','compose-city'].includes(select.id);if(city){const p=select.id==='join-city'?joinDraft:select.id==='edit-city'?me():composerData,list=select.id+'-locations',input=document.createElement('input');input.id=select.id;input.setAttribute('list',list);input.setAttribute('aria-label','Search city or town and country');input.placeholder='Search city / town, country';input.value=select.value+(p.country?', '+p.country:locationDirectory.find(x=>x.city===select.value)?', '+locationDirectory.find(x=>x.city===select.value).country:'');select.replaceWith(input);input.insertAdjacentHTML('afterend',`<datalist id="${list}">${locationDirectory.map(x=>`<option value="${esc(x.city+', '+x.country)}"></option>`).join('')}</datalist><small class="form-help">Choose a result, or enter your town followed by a comma and country.</small>`);continue}if(select.options.length<7)continue;select.dataset.searchEnhanced='true';if(!select.id)select.id='search-select-'+uid();const search=document.createElement('input');search.type='search';search.className='select-search';search.placeholder='Search '+(select.getAttribute('aria-label')||'options');search.setAttribute('aria-label','Search '+(select.getAttribute('aria-label')||'options'));search.setAttribute('aria-controls',select.id);const original=[...select.options].map(o=>o.cloneNode(true));search.addEventListener('input',()=>{const selected=select.value,q=search.value.toLocaleLowerCase(),matched=original.filter(o=>!q||o.textContent.toLocaleLowerCase().includes(q)||o.value===selected||!o.value);select.replaceChildren(...matched.map(o=>o.cloneNode(true)));select.value=selected});select.before(search)}}
const modalExperienceBase=modal;
modal=function(...args){modalExperienceBase(...args);enhanceSearches();document.querySelectorAll('#modal input,#modal textarea,#modal select').forEach((el,i)=>{if(['checkbox','radio','file'].includes(el.type))return;if(!el.id)el.id='dialog-field-'+i;const label=el.previousElementSibling;if(label?.tagName==='LABEL'&&!label.htmlFor)label.htmlFor=el.id;else if(!el.getAttribute('aria-label')&&!document.querySelector('label[for="'+el.id+'"]'))el.setAttribute('aria-label',el.placeholder||'Details')})};
const captureJoinExperience=captureJoin;
captureJoin=function(){captureJoinExperience();if(joinStep===1){Object.assign(joinDraft,parseLocation(joinDraft.city,joinDraft.country));joinDraft.entityType=document.getElementById('join-entity-type')?.value||joinDraft.entityType||'person'}};
const renderJoinExperience=renderJoin;
renderJoin=function(){let html=renderJoinExperience();if(joinStep===1)html=html.replace('<label>Your name / business name</label>',`<label>Profile identity</label><select id="join-entity-type"><option value="person" ${joinDraft.entityType!=='business'?'selected':''}>Person</option><option value="business" ${joinDraft.entityType==='business'?'selected':''}>Business / company</option></select><p class="meta">People and businesses share the same work and team features. Credits identify each contributor separately.</p><label>Your name / business name</label>`);return html};
const editProfileExperience=editProfile;
editProfile=function(){editProfileExperience();document.getElementById('edit-bio')?.insertAdjacentHTML('beforebegin',`<label>Profile identity</label><select id="edit-entity-type"><option value="person" ${me().entityType!=='business'?'selected':''}>Person</option><option value="business" ${me().entityType==='business'?'selected':''}>Business / company</option></select>`);enhanceSearches()};
const saveProfileExperience=saveProfile;
saveProfile=async function(){const p=me();p.entityType=document.getElementById('edit-entity-type')?.value||'person';const el=document.getElementById('edit-city');if(el){Object.assign(p,parseLocation(el.value,p.country));el.value=p.city}return saveProfileExperience()};
// A unified Office inbox shows conversations and actionable requests together.
function inboxEvents(){return [
 ...state.invitations.map(i=>({kind:'invitation',id:i.id,title:i.title,detail:(i.type==='credit'?'Credit invitation':'Team invitation')+' · '+i.status,person:i.to==='me'?i.from:i.to,status:i.status})),
 ...state.applications.map(a=>({kind:'application',id:a.id,title:state.opps.find(o=>o.id===a.opp)?.title||'Application',detail:'Application · '+a.status,person:a.person,status:a.status})),
 ...state.requests.map(r=>({kind:'booking',id:r.id,title:r.title,detail:'Booking · '+r.status,person:r.to==='me'?r.from:r.to,status:r.status})),
 ...agentRequests.map(r=>({kind:'agent',id:r.id,title:'Agent invitation',detail:'Representation · '+r.status,person:idMap({id:r.from===account.profile?.id?r.to:r.from},account.profile?.id,'me').id,status:r.status,created:r.created})),
 ...officeProjects.filter(p=>p.status==='Invitation').map(p=>({kind:'project',id:p.id,title:p.title,detail:'Workspace invitation',person:idMap({id:p.owner},account.profile?.id,'me').id,status:'Pending'}))
 ].sort((a,b)=>(b.status==='Pending'||b.status==='Requested'||b.status==='Sent')-(a.status==='Pending'||a.status==='Requested'||a.status==='Sent')||(b.created||'').localeCompare(a.created||''))}
renderInbox=function(){const events=inboxEvents();let messages=renderMessages();const items=events.map(e=>`<button class="conversation-row inbox-event" onclick="openInboxEvent('${e.kind}','${e.id}')"><div class="row between"><b>${esc(e.title)}</b>${['Pending','Requested','Sent'].includes(e.status)?'<span class="unread-dot" aria-label="Needs attention"></span>':''}</div><p>${esc(person(e.person)?.name||'Member')} · ${esc(e.detail)}</p></button>`).join('');messages=messages.replace(/<div class="conversation-list ([^"]*)">/,`<div class="conversation-list $1">${items}`);if(events.length)messages=messages.replace('<h3>No conversations yet.</h3>','<h3>Start a conversation.</h3>');return `<div class="heading"><div class="row between wrap"><h1>Inbox<span class="red">.</span></h1><button class="btn primary" onclick="newMessage()">New message</button></div><p>Messages, invitations, applications and bookings. One place to respond.</p></div>${messages}`};
async function openInboxEvent(kind,id){if(kind==='invitation'){const i=state.invitations.find(x=>x.id===id);modal(i.title,`<p>${esc(i.role)} · ${esc(i.status)}</p><p>${i.to==='me'?'From':'To'} ${esc(person(i.to==='me'?i.from:i.to)?.name||i.name||'Member')}</p>`,`<button class="btn" onclick="closeModal()">Done</button>${i.to==='me'&&i.status==='Pending'?`<button class="btn" onclick="respondInvitation('${id}','Declined');closeModal()">Decline</button><button class="btn primary" onclick="respondInvitation('${id}','Accepted');closeModal()">Accept</button>`:''}<button class="btn" onclick="${i.type==='credit'?`openWork('${i.post}')`:`openOpportunity('${i.post}')`}">Open work</button>`)}else if(kind==='application'){const a=state.applications.find(x=>x.id===id);openOpportunity(a.opp)}else if(kind==='booking'){setOfficeDesk('bookings')}else if(kind==='project'){modal('Workspace invitation',`<h3>${esc(officeProjects.find(p=>p.id===id)?.title)}</h3>`,'<button class="btn" onclick="closeModal()">Done</button>'+`<button class="btn primary" onclick="closeModal();acceptProject('${id}')">Accept workspace</button>`)}else{const r=agentRequests.find(x=>x.id===id),incoming=r.to===account.profile.id;modal('Agent invitation',`<p>${esc(contributionPerson(r.from)?.name||'Member')} invited ${esc(contributionPerson(r.to)?.name||'a member')} to represent them.</p><p>${esc(r.status)}</p><ul>${Object.entries(r.scopes).filter(([,v])=>v).map(([k])=>`<li>${esc(agentScopeLabels[k])}</li>`).join('')}</ul><p>Access starts only after acceptance. The owner can revoke it in Settings.</p>`,`<button class="btn" onclick="closeModal()">Done</button>${r.status==='Pending'?incoming?`<button class="btn" onclick="respondAgent('${id}','Declined')">Decline</button><button class="btn primary" onclick="respondAgent('${id}','Accepted')">Accept access</button>`:`<button class="btn" onclick="respondAgent('${id}','Cancelled')">Cancel invitation</button>`:''}`)}}
const navExperienceBase=nav;
nav=function(v){if(v==='inbox'||v==='bookings'){officeDesk=v;v='office'}return navExperienceBase(v)};
const respondInvitationExperience=respondInvitation;
respondInvitation=async function(...args){await respondInvitationExperience(...args);officeDesk='inbox';view='office';render()};
const agentScopeLabels={read:'View private fees',edit:'Edit gig records',book:'Manage booking requests',inbox:'Read inbox',reply:'Reply on my behalf',approve:'Manage project workspaces and approve budget / scope'};
grantAccess=function(){const members=state.profiles.filter(p=>p.id!=='me');modal('Invite someone to be your agent',`<p>Anyone on TAPPED IN can be your agent. Choose a person or business you trust. They must accept before any access is granted.</p><label>Member</label><select id="access-person"><option value="">Choose a member</option>${members.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(identityCategory(p))}</option>`).join('')}</select>${Object.entries(agentScopeLabels).map(([k,l])=>`<label class="radio-row"><input type="checkbox" id="access-${k}">${l}</label>`).join('')}<div id="form-error" class="error"></div>`,'<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveAccess()">Send agent invitation</button>')};
saveAccess=async function(){const data={person:realMember(document.getElementById('access-person').value)};for(const k of Object.keys(agentScopeLabels))data[k]=document.getElementById('access-'+k).checked;try{await api('/api/v3/agent-requests','POST',data);agentRequests=(await api('/api/v3/agent-requests')).requests;closeModal();render();toast('Agent invited. Access begins after they accept.')}catch(e){error(e.message)}};
async function respondAgent(id,status){try{await api('/api/v3/agent-requests/'+id,'POST',{status});await refreshAccount();memberAccess=(await api('/api/represented')).members;closeModal();render();toast(status==='Accepted'?'Agent access accepted.':status==='Cancelled'?'Invitation cancelled.':'Invitation declined.')}catch(e){error(e.message)}}
const settingsExperienceBase=renderSettings;
renderSettings=function(){return settingsExperienceBase().replace('Fees stay out of your public profile.','Individual fees stay private. You can choose to publish the total below.')+`<section class="settings-block"><h3>Password</h3><p>Change your password securely using your current password.</p><button class="btn" onclick="changePasswordForm()">Change password</button></section><section class="settings-block"><h3>Total Fees recorded</h3><p>Private by default. Sharing publishes only your total, never individual fees or payment records.</p><label class="radio-row"><input type="checkbox" ${me().showFees?'checked':''} onchange="togglePublicFees(this.checked)">Show my total publicly</label></section>${agentRequests.some(r=>r.from===account.profile?.id&&r.status==='Pending')?`<section class="settings-block"><h3>Pending agent invitations</h3>${agentRequests.filter(r=>r.from===account.profile.id&&r.status==='Pending').map(r=>`<div class="office-row"><b>${esc(contributionPerson(r.to)?.name||'Member')}</b><button class="btn" onclick="respondAgent('${r.id}','Cancelled')">Cancel invitation</button></div>`).join('')}</section>`:''}`};
async function togglePublicFees(value){const old=me().showFees;me().showFees=value;try{await save();toast(value?'Your total is now public.':'Your fees total is private.')}catch{me().showFees=old;render()}}
function changePasswordForm(){modal('Change password',`<form id="change-password-form" onsubmit="event.preventDefault();submitPasswordChange()"><label for="current-password">Current password</label><input id="current-password" type="password" autocomplete="current-password" required maxlength="1024"><label for="new-password">New password</label><input id="new-password" type="password" autocomplete="new-password" minlength="10" maxlength="1024" required><label for="confirm-password">Confirm new password</label><input id="confirm-password" type="password" autocomplete="new-password" required><p>Use at least 10 characters.</p><div id="form-error" class="error" role="alert"></div></form>`,'<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" id="password-submit" form="change-password-form" type="submit">Change password</button>')}
async function submitPasswordChange(){const currentPassword=document.getElementById('current-password').value,password=document.getElementById('new-password').value;if(password!==document.getElementById('confirm-password').value)return error('The new passwords do not match.');const button=document.getElementById('password-submit');button.disabled=true;try{await api('/api/auth/change-password','POST',{currentPassword,password});document.getElementById('change-password-form').reset();closeModal();toast('Password changed.')}catch(e){error(e.message)}finally{if(button.isConnected)button.disabled=false}}
function contactsMarkup(){return `<div class="heading"><div class="row between wrap"><h1>Contacts</h1><button class="btn primary" onclick="editOfficeContact()">Add contact</button></div><p>People and businesses, including contacts who haven’t joined yet.</p></div><div class="search">${icon('search')}<input id="contacts-search" type="search" placeholder="Search names, categories, email or location" aria-label="Search contacts" oninput="filterOfficeContacts(this.value)"></div><div id="contacts-results">${officeContacts.map(c=>`<article class="office-row contact-row" data-search="${esc([c.name,c.category,c.role,c.email,c.city].join(' ').toLocaleLowerCase())}"><div><h3>${esc(c.name)}</h3><p>${esc(c.category)} · ${esc(c.role)}</p><p class="meta">${esc(c.email||'')}${c.phone?' · '+esc(c.phone):''}</p><small>${c.member?'Linked profile':'Awaiting signup'}</small></div><div class="row wrap gap8"><button class="btn" onclick="editOfficeContact('${c.id}')">Edit</button>${c.member?`<button class="btn" onclick="syncOfficeContact('${c.id}')">Sync profile</button><button class="text-btn" onclick="openProfile('${idMap({id:c.member},account.profile.id,'me').id}')">Profile</button>`:`<button class="btn" onclick="shareContact('${c.id}')">Invite</button>`}<button class="text-btn danger" onclick="deleteOfficeContact('${c.id}')">Delete</button></div></article>`).join('')||'<div class="empty"><h3>Your network starts here.</h3><p>Add a contact or invite them to TAPPED IN.</p></div>'}</div>`}
function filterOfficeContacts(q){document.querySelectorAll('.contact-row').forEach(r=>r.hidden=!searchMatches([r.dataset.search],q))}
function editOfficeContact(id=''){const c=officeContacts.find(c=>c.id===id)||{};modal(id?'Edit contact':'Add contact',`<label>Name / business</label><input id="contact-name" maxlength="100" value="${esc(c.name||'')}">${identityFields('contact',{category:c.category,primaryRole:c.role,roles:[c.role||'Artist']})}<label>Email</label><input id="contact-email" type="email" maxlength="150" value="${esc(c.email||'')}"><label>Phone</label><input id="contact-phone" type="tel" maxlength="40" value="${esc(c.phone||'')}"><label>Private notes</label><textarea id="contact-notes" maxlength="1000">${esc(c.notes||'')}</textarea><div id="form-error" class="error"></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveOfficeContact('${id}')">Save contact</button>`)}
async function saveOfficeContact(id){const data={name:document.getElementById('contact-name').value,category:document.getElementById('contact-category').value,role:document.getElementById('contact-primary').value,email:document.getElementById('contact-email').value,phone:document.getElementById('contact-phone').value,notes:document.getElementById('contact-notes').value};try{const result=await api('/api/v3/contacts'+(id?'/'+id:''),'POST',data);if(!id&&(data.email||data.phone||data.notes))await api('/api/v3/contacts/'+result.contact.id,'POST',data);officeContacts=(await api('/api/v3/contacts')).contacts;closeModal();officeDesk='contacts';nav('office')}catch(e){error(e.message)}}
async function deleteOfficeContact(id){if(!confirm('Delete this contact? Their profile and existing credits will remain.'))return;try{await api('/api/v3/contacts/'+id,'DELETE');officeContacts=(await api('/api/v3/contacts')).contacts;render()}catch(e){toast(e.message)}}
async function syncOfficeContact(id){try{await api('/api/v3/contacts/'+id+'/sync','POST',{});officeContacts=(await api('/api/v3/contacts')).contacts;render();toast('Contact synced with their accepted profile link.')}catch(e){toast(e.message)}}
const officeExperienceBase=renderOffice;
renderOffice=function(){let html;if(officeDesk==='contacts')html=`<div class="office-tabs office-desk-tabs">${[['inbox','Inbox'],...(!fan()?[['bookings','Bookings']]:[]),['teams','Teams'],['projects','Projects'],['contacts','Contacts']].map(([d,l])=>`<button class="${officeDesk===d?'active':''}" onclick="setOfficeDesk('${d}')">${l}</button>`).join('')}</div>`+contactsMarkup();else html=officeExperienceBase().replace(/(<div class="office-tabs office-desk-tabs">[\s\S]*?)(<\/div>)/,'$1<button onclick="setOfficeDesk(\'contacts\')">Contacts</button>$2');return html.replace(/Inbox \/ 0(?=<)/g,'Inbox')};
function taskEditor(id){const task=officeProject.tasks.find(x=>x.id===id);if(!task)return;const owner=officeProject.owner===account.profile.id,editable=owner||task.assignee===account.profile.id;modal(editable?'Manage task':'Task',`<label>Task title</label><input id="task-title" maxlength="200" value="${esc(task.title)}" ${editable?'':'readonly'}><label>Assignee</label><select id="task-assignee" ${owner?'':'disabled'}>${officeMemberOptions(task.assignee)}</select><label>Due date</label><input id="task-due" type="date" value="${task.due||''}" ${editable?'':'readonly'}><label>Status</label><select id="task-status" ${editable?'':'disabled'}>${options(['To do','In progress','Done'],task.status)}</select><div id="form-error" class="error"></div>`,`<button class="btn" onclick="closeModal()">Done</button>${editable?`<button class="btn" onclick="deleteOfficeTask('${id}')">Remove task</button><button class="btn primary" onclick="saveOfficeTask('${id}')">Save changes</button>`:''}`)}
async function saveOfficeTask(id){await officeAction({action:'taskedit',task:id,title:document.getElementById('task-title').value,due:document.getElementById('task-due').value,assignee:document.getElementById('task-assignee').value,status:document.getElementById('task-status').value})}
async function deleteOfficeTask(id){if(confirm('Remove this task from the project?'))await officeAction({action:'taskdelete',task:id})}
function scheduleProjectForm(){const p=officeProject;modal('Project calendar',`<label>Project / event date</label><input id="project-date" type="date" value="${p.date||''}"><label class="radio-row"><input id="project-calendar-public" type="checkbox" ${p.publicCalendar?'checked':''}>Show this project title and date on my public calendar</label><p>Private project schedules and task deadlines appear only in your own calendar. Publishing never exposes tasks, fees, files or messages.</p><div id="form-error" class="error"></div>`,'<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveProjectSchedule()">Save schedule</button>')}
async function saveProjectSchedule(){const ok=await officeAction({action:'schedule',date:document.getElementById('project-date').value,publicCalendar:document.getElementById('project-calendar-public').checked});if(ok)publicCalendarEvents.delete(account.profile.id)}
const projectOfficeExperience=projectOffice;
projectOffice=function(){let html=projectOfficeExperience();if(!officeProject)return html;const p=officeProject;if(officeTab==='tasks'){for(const t of p.tasks)html=html.replace(`<b>${esc(t.title)}</b>`,`<button class="task-open" onclick="taskEditor('${t.id}')">${esc(t.title)}</button>`)}if(officeTab==='overview'){html+=`<section class="settings-block"><h3>Project calendar</h3><p>${p.date?fmt(p.date):'No date set'} · ${p.publicCalendar?'Public date':'Private schedule'}</p>${p.owner===account.profile.id?'<button class="btn" onclick="scheduleProjectForm()">Set date & visibility</button>':''}</section>`;if(p.budgetItems?.length)html+=`<section class="settings-block"><h3>Approved budget items</h3>${budgetItemsMarkup(p.budgetItems)}</section>`}if(officeTab==='approvals')for(const a of p.approvals)if(a.items?.length)html=html.replace(`<p class="office-document">${esc(a.scope)}</p>`,`<p class="office-document">${esc(a.scope)}</p>${budgetItemsMarkup(a.items)}`);return html};
function budgetItemsMarkup(items){return `<div class="budget-items">${items.map(i=>`<div class="row between wrap"><span>${esc(i.description)} · ${i.quantity} × ${money(i.rate)}</span><b>${money(i.quantity*i.rate)}</b></div>`).join('')}</div>`}
const officeFormExperience=officeForm;
officeForm=function(action,id=''){officeFormExperience(action,id);if(action==='proposal'){const total=document.getElementById('of-budget');total.readOnly=true;total.insertAdjacentHTML('beforebegin',`<label>Budget breakdown</label><div id="proposal-items">${(officeProject.budgetItems?.length?officeProject.budgetItems:officeProject.budget?[{description:'Project costs',quantity:1,rate:officeProject.budget}]:[{}]).map(i=>budgetEditorRow(i)).join('')}</div><button class="text-btn" onclick="addBudgetItem()">Add budget item</button>`);document.getElementById('proposal-items').addEventListener('input',updateBudgetTotal);updateBudgetTotal()}enhanceSearches()};
function budgetEditorRow(i={}){return `<div class="budget-item-row"><input class="budget-description" aria-label="Budget item description" maxlength="200" value="${esc(i.description||'')}" placeholder="Service, crew, equipment…"><input class="budget-quantity" aria-label="Budget item quantity" type="number" min="0.01" step="0.01" value="${i.quantity??1}"><input class="budget-rate" aria-label="Budget item rate" type="number" min="0" step="0.01" value="${i.rate??0}"><button aria-label="Remove budget item" onclick="this.parentElement.remove();updateBudgetTotal()">${icon('close')}</button></div>`}
function addBudgetItem(){document.getElementById('proposal-items').insertAdjacentHTML('beforeend',budgetEditorRow());updateBudgetTotal()}
function getBudgetItems(){return [...document.querySelectorAll('.budget-item-row')].map(r=>({description:r.querySelector('.budget-description').value.trim(),quantity:Number(r.querySelector('.budget-quantity').value),rate:Number(r.querySelector('.budget-rate').value)}))}
function updateBudgetTotal(){const el=document.getElementById('of-budget');if(el)el.value=getBudgetItems().reduce((n,i)=>n+i.quantity*i.rate,0).toFixed(2)}
const saveOfficeFormExperience=saveOfficeForm;
saveOfficeForm=async function(action,id){if(action!=='proposal')return saveOfficeFormExperience(action,id);const items=getBudgetItems();if(!items.length||items.some(x=>!x.description||x.quantity<=0||x.rate<0))return error('Add valid budget items, quantities and rates.');return officeAction({action,items,budget:items.reduce((n,x)=>n+x.quantity*x.rate,0),scope:document.getElementById('of-scope').value})};
// Public website names every role family and explains consent-based representation.
const landingExperienceBase=renderLanding;
renderLanding=function(){return landingExperienceBase().replace(/<div class="home-audience-grid">[\s\S]*?<\/div><p class="home-subhead">Whatever your role, there’s a place for you\.<\/p>/,`<div class="home-audience-grid all-role-grid">${Object.entries(roleCategories).map(([category,rs],i)=>`<article><span class="red">${String(i+1).padStart(2,'0')}</span><h3>${esc(category)}</h3><p>${rs.map(esc).join(' · ')}</p></article>`).join('')}<article><span class="red">FANS</span><h3>Fans & supporters</h3><p>Follow the work, give stars, share your perspective and stay connected.</p></article></div><p class="home-subhead">People and companies. Every role has a place.</p>`).replace('<section class="home-section home-how"',`<section class="home-section home-agent-feature" id="agents"><div class="eyebrow">YOUR TEAM, YOUR PERMISSIONS</div><h2>ANYONE YOU TRUST<br>CAN BE YOUR AGENT.</h2><p>Invite a person or company to represent you. They accept before access begins. Their profile doesn’t need an Agent role.</p><div class="home-agent-grid"><article><h3>Choose what you share</h3><p>Allow specific access to fees, gig records, booking requests, your inbox or project approvals.</p></article><article><h3>Stay in control</h3><p>Reading, replying and final approval are separate permissions. Agent replies identify who sent them. Revoke access at any time.</p></article><article><h3>Keep the work together</h3><p>Your agent works alongside your projects, bookings and conversations in Office.</p></article></div><a class="btn primary" href="/signup">Build your trusted team</a></section><section class="home-section home-how"`)};
let shareSnapshotUrl='';
sharePost=async function(id){const p=state.posts.find(x=>x.id===id)||contributions.find(x=>x.id===id);if(!p)return;const data=p.opp?state.opps.find(o=>o.id===p.opp):p,link=location.origin+'/post/'+id;modal('Share this post',`<p>Share the public link and copy, or create an image of the whole post card.</p><label>Post link</label><input id="public-post-link" readonly value="${esc(link)}"><label>Share copy</label><textarea id="post-share-copy">${esc(data.title+'\n'+data.description+'\n'+link)}</textarea><label>Snapshot background</label><select id="snapshot-background">${options(['white','black'],'white')}</select><div class="row wrap gap8"><button class="btn" id="snapshot-create" onclick="generatePostSnapshot('${id}')">Create snapshot image</button><button class="btn" onclick="nativeSharePost('${id}')">Share link</button><button class="btn" onclick="copyPostText()">Copy text & link</button></div><div id="snapshot-preview" aria-live="polite"></div><div id="form-error" class="error" role="alert"></div>`,'<button class="btn" onclick="closeModal()">Done</button><button class="btn primary" onclick="copyPostLink()">Copy link</button>')};
async function copyPostText(){const el=document.getElementById('post-share-copy');try{await navigator.clipboard.writeText(el.value);toast('Share text and link copied.')}catch{el.select();toast('Select and copy the text.')}}
async function nativeSharePost(id){const p=state.posts.find(x=>x.id===id)||contributions.find(x=>x.id===id),d=p?.opp?state.opps.find(o=>o.id===p.opp):p;if(!navigator.share)return copyPostText();try{await navigator.share({title:d.title,text:d.description,url:location.origin+'/post/'+id})}catch(e){if(e.name!=='AbortError')toast('Sharing is unavailable. Copy the link or download the snapshot.')}}
function canvasLines(ctx,text,width){const lines=[];for(const paragraph of String(text||'').split('\n')){let line='';for(const word of paragraph.split(/\s+/)){if(ctx.measureText(word).width>width){if(line){lines.push(line);line=''}let part='';for(const ch of word){if(ctx.measureText(part+ch).width>width){lines.push(part);part=''}part+=ch}line=part;continue}const next=line?line+' '+word:word;if(ctx.measureText(next).width>width&&line){lines.push(line);line=word}else line=next}lines.push(line)}return lines}
async function snapshotImage(src){if(!src)return null;try{const img=new Image();if(!src.startsWith('/'))img.crossOrigin='anonymous';img.src=src;await Promise.race([img.decode(),new Promise((_,reject)=>setTimeout(()=>reject(new Error('Image timed out')),8000))]);return img}catch{return null}}
async function generatePostSnapshot(id){const button=document.getElementById('snapshot-create');button.disabled=true;button.textContent='Creating image…';try{const p=state.posts.find(x=>x.id===id)||contributions.find(x=>x.id===id),d=p.opp?state.opps.find(o=>o.id===p.opp):p,by=contributionPerson(d.by)||{name:'Member'},dark=document.getElementById('snapshot-background').value==='black',bg=dark?'#000':'#fff',fg=dark?'#fff':'#000',mut=dark?'#bbb':'#555',canvas=document.createElement('canvas'),ctx=canvas.getContext('2d'),width=1080,pad=56,contentWidth=width-pad*2,src=d.image||thumbnailCache.get(d.id)||youtubeThumbnail(d),img=await snapshotImage(src);const blocks=[];const add=(text,size=28,color=fg,bold=false,gap=20)=>{ctx.font=`${bold?700:400} ${size}px Arial`;const lines=canvasLines(ctx,text,contentWidth);blocks.push({lines,size,color,bold,gap,height:lines.length*size*1.4+gap})};add('TAPPED IN',48,'#a41627',true,28);add(by.name,36,fg,true,8);add([identityCategory(by),d.date,d.date>localDate()?'Upcoming work':''].filter(Boolean).join(' · '),24,'#a41627',false,24);const headingIndex=blocks.length;add(d.title,52,fg,true,28);add(d.description,30,fg,false,24);for(const key of ['project','team'])if(d[key])add((key==='team'?'Team':'Project')+': '+(d[key+'Name']||officeProjects.find(x=>x.id===d[key])?.title||'Tagged '+key),24,'#a41627');if(d.type==='checkin')add([d.venueName,d.event].filter(Boolean).join(' · '),28,fg,true);if(d.credits?.length){add('People & partners',24,'#a41627',true,12);for(const c of d.credits)add((person(c.id||c.pendingId)?.name||c.name||'Contributor')+' · '+c.role+(c.id?'':' · Awaiting confirmation'),26,'#a41627',false,10)}for(const t of d.businessTags||[])add(t.name+' · '+t.role,26,'#a41627',false,10);for(const t of d.tags||[])add((contributionPerson(t.person)?.name||'Member')+' · '+t.relation,26,'#a41627');if(d.roles?.length)add('Roles: '+d.roles.join(' / '),26,fg);if(d.budget!==undefined)add('Budget: '+money(d.budget),28,fg,true);for(const l of d.links||[])add(l.platform,24,mut,false,12);add('★ '+(Number(p.likes||d.likes||0)+(state.likes.includes(id)?1:0))+'    '+(state.saved.includes(id)?'Saved':'Save')+'    Share',26,fg,false,24);const heading=blocks[headingIndex],imageHeight=img?Math.max(d.imageOrientation==='square'?contentWidth:Math.round(contentWidth*9/16),heading.height+80):0;canvas.width=width;canvas.height=Math.ceil(pad*2+blocks.reduce((n,b)=>n+b.height,0)+(img?Math.max(0,imageHeight-heading.height)+24:0));ctx.fillStyle=bg;ctx.fillRect(0,0,width,canvas.height);let y=pad;for(let i=0;i<blocks.length;i++){const block=blocks[i];if(i===headingIndex&&img){ctx.save();const ratio=Math.max(contentWidth/img.naturalWidth,imageHeight/img.naturalHeight),w=img.naturalWidth*ratio,h=img.naturalHeight*ratio;ctx.beginPath();ctx.rect(pad,y,contentWidth,imageHeight);ctx.clip();ctx.drawImage(img,pad+(contentWidth-w)/2,y+(imageHeight-h)/2,w,h);const gradient=ctx.createLinearGradient(0,y+imageHeight*.2,0,y+imageHeight);gradient.addColorStop(0,'rgba(0,0,0,0)');gradient.addColorStop(1,'rgba(0,0,0,.95)');ctx.fillStyle=gradient;ctx.fillRect(pad,y,contentWidth,imageHeight);ctx.restore();ctx.font='700 52px Arial';ctx.fillStyle='#fff';const titleHeight=block.lines.length*52*1.4;let titleY=y+imageHeight-titleHeight;for(const line of block.lines){ctx.fillText(line,pad+24,titleY+52);titleY+=52*1.4}y+=imageHeight+24;continue}ctx.font=`${block.bold?700:400} ${block.size}px Arial`;ctx.fillStyle=block.color;for(const line of block.lines){ctx.textAlign=i===0?'center':'left';ctx.fillText(line,i===0?width/2:pad,y+block.size);ctx.textAlign='left';y+=block.size*1.4}y+=block.gap}const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw new Error('This image could not be created.');if(shareSnapshotUrl)URL.revokeObjectURL(shareSnapshotUrl);shareSnapshotUrl=URL.createObjectURL(blob);document.getElementById('snapshot-preview').innerHTML=`${src&&!img?'<p class="meta">The external preview image could not be included. All post text, credits and links are included.</p>':''}<img src="${shareSnapshotUrl}" alt="Complete shareable post card"><a class="btn primary" href="${shareSnapshotUrl}" download="tapped-in-${id}.png">Download snapshot</a><button class="btn" onclick="shareSnapshotFile('${id}')">Share image & link</button>`;window.postSnapshotBlob=blob}catch(e){error(e.message)}finally{if(button.isConnected){button.disabled=false;button.textContent='Create snapshot image'}}}
async function shareSnapshotFile(id){const file=new File([window.postSnapshotBlob],'tapped-in-'+id+'.png',{type:'image/png'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],text:document.getElementById('post-share-copy').value});return}catch(e){if(e.name==='AbortError')return}}toast('Download the snapshot, then copy the share text and link. Your social app may handle images and captions separately.')}
const confirmDeleteExperience=confirmDeletePost;
confirmDeletePost=async function(id){const old=me().highlights||[];me().highlights=old.filter(x=>x!==id);try{return await confirmDeleteExperience(id)}catch(e){me().highlights=old;throw e}};

const markOfficeReadExperience=markOfficeRead;
markOfficeRead=async function(){await markOfficeReadExperience();updateOfficeBadges()};
